import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { Orbit, DepthRotate, DissolveMorph, DisplacementTransition, ParallaxScroll, MagneticCursor, ParticleEmerge, FlyThrough, KineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container – positioning handled by the adapter
  const root = new Group();

  // Geometry for the card plane (default size, can be overridden by styling)
  const geometry = new PlaneGeometry(1, 0.6);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true, opacity: 0 });

  // Mesh
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; function stays synchronous
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.opacity = 1;
      material.needsUpdate = true;
    });
  }

  // ---------- Interactions ----------
  // Hover lift (rise‑in) – subtle 0.15 scene units upward
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    plane.position,
    {
      y: 0.15,
      duration: 0.3,
      ease: 'power3.out',
    }
  );

  // Click press‑down (scale) + emit event
  const clickTimeline = gsap.timeline({ paused: true });
  clickTimeline
    .to(
      plane.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      }
    )
    .to(
      plane.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.1,
        ease: 'power2.out',
      },
      '+=0.05'
    );

  // Attach handlers to userData for external event routing
  root.userData.handlers = {
    hoverEnter: () => hoverTimeline.play(),
    hoverLeave: () => hoverTimeline.reverse(),
    click: () => {
      clickTimeline.restart();
      ctx.emit('hub-collection.select', {});
    },
  };

  // ---------- Cinematic primitives ----------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params ?? {});
        primitiveInstances.push(instance);
        // If a trigger is defined, the primitive itself will handle it;
        // otherwise we keep a reference for cleanup.
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    hoverTimeline.kill();
    clickTimeline.kill();
    material.dispose();
    geometry.dispose();
    if (material.map && material.map.dispose) material.map.dispose();
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return root;
}
